c='p6';B='AI 1'
S=[]
S.append(TITLE('TIN HỌC · AI 1','TRÍ TUỆ NHÂN TẠO:<br>KHÁI NIỆM, ỨNG DỤNG, ĐẠO ĐỨC','AI là gì và không là gì; bốn khả năng đặc trưng; AI hẹp – AI tổng quát; AI tạo sinh; ứng dụng theo lĩnh vực; thiên lệch dữ liệu, ảo giác, quyền riêng tư và trách nhiệm.',['AI','4 khả năng','AI hẹp','AI tạo sinh','đạo đức']))
S.append(goals(c,B,['Phân biệt <b>AI</b> với <b>tự động hoá</b> thông thường.','Nhận ra <b>4 khả năng</b>: học, suy luận, nhận thức, hiểu ngôn ngữ (và giải quyết vấn đề).','Phân biệt <b>AI hẹp</b>, <b>AI tổng quát</b>, <b>AI tạo sinh</b>.','Nêu ứng dụng AI theo lĩnh vực: y tế, giáo dục, tài chính, giao thông…','Nhận diện rủi ro: <b>thiên lệch, ảo giác, quyền riêng tư, việc làm</b>.'],['AI và tự động hoá','Đặc trưng của AI','Các loại AI','Ứng dụng','Đạo đức và cảnh báo']))
S.append(S2(c,B+' · 1','AI khác tự động hoá ở đâu?',card('Chìa khoá',P('<b>Tự động hoá</b>: lặp lại <b>thao tác cố định</b> theo kịch bản (dây chuyền lắp ráp, ấm tự ngắt điện, guồng nước).','<b>AI</b>: hệ thống có khả năng <b>học, suy luận, nhận thức, hiểu ngôn ngữ, giải quyết vấn đề mới</b>.','Có chạy trên máy tính hay có hình dạng robot <b>chưa đủ</b> để gọi là AI.')),T(tr('Hệ thống','AI?',h=True)+tr('Gợi ý video học từ lịch sử xem','<b>Có</b> (học)')+tr('Dây chuyền lắp ráp cố định','Không')+tr('Ấm tự ngắt khi sôi (cảm nhiệt)','Không')+tr('Chatbot chỉ “gõ 1, gõ 2”','Không (kịch bản)'))+KEY('Hỏi: hệ thống có <b>học / suy luận từ dữ liệu</b> hay chỉ làm lại thao tác cố định?')))
S.append(S2(c,B+' · 1','Mốc lịch sử',card('Hai cột mốc',T(tr('Năm','Sự kiện',h=True)+tr('<b>1950</b>','Alan Turing đề xuất <b>phép thử Turing</b>: máy có hành vi giống người đến mức người hỏi không phân biệt được')+tr('<b>1956</b>','<b>Hội thảo Dartmouth</b>: thuật ngữ <b>“trí tuệ nhân tạo”</b> ra đời')+tr('2022','ChatGPT: bước đột phá của <b>AI tạo sinh</b>'))),KEY('Nhớ cặp: <b>1950 – Turing</b>; <b>1956 – Dartmouth</b>.')))
S.append(S2(c,B+' · 2','Năm khả năng đặc trưng của AI',card('Nhận ra qua ví dụ',T(tr('Khả năng','Ví dụ',h=True)+tr('<b>Học</b>','gợi ý video tự chỉnh theo thói quen xem')+tr('<b>Suy luận</b>','chẩn đoán y tế từ triệu chứng và tri thức bệnh lí')+tr('<b>Nhận thức</b>','xe tự lái dùng radar, camera thấy xe, biển báo')+tr('<b>Hiểu ngôn ngữ</b>','trợ lí ảo nghe và hiểu câu lệnh')+tr('<b>Giải quyết vấn đề</b>','dự báo thời tiết từ dữ liệu nhiều năm'))),KEY('Cảm biến → <b>nhận thức</b>; luật + tri thức → <b>suy luận</b>; dữ liệu mới → <b>học</b>.')))
S.append(S2(c,B+' · 2','Phân biệt khi một ví dụ có nhiều khả năng',card('Chọn khả năng “rõ nhất”',P('“Bật điều hoà 26 độ”: trợ lí <b>hiểu ngôn ngữ</b> (nghe lệnh) và <b>giải quyết vấn đề</b> (làm đúng yêu cầu).','Gợi ý video <b>tự điều chỉnh</b> khi người dùng bỏ qua: nhấn mạnh <b>học</b> từ phản hồi.','Xe tự lái: chủ yếu <b>nhận thức</b> (cảm biến), rồi mới đến suy luận.')),KEY('Đọc kĩ <b>động từ</b> trong đề: “cảm nhận”, “rút kinh nghiệm”, “kết luận từ luật”.')))
S.append(S2(c,B+' · 3','AI hẹp và AI tổng quát',card('Hai mức',T(tr('Loại','Đặc điểm',h=True)+tr('<b>AI hẹp (yếu)</b>','làm tốt <b>một nhiệm vụ cụ thể</b> (chơi cờ, nhận mặt, dịch)')+tr('<b>AI tổng quát (mạnh)</b>','trí tuệ <b>như con người</b>, tự học, thích nghi nhiều việc; <b>mục tiêu dài hạn</b>')),P('Mọi AI hiện nay, <b>kể cả ChatGPT</b>, vẫn là <b>AI hẹp</b>.')),KEY('Chương trình chỉ chơi cờ vua: <b>AI hẹp</b>, không phải AI tổng quát.')))
S.append(S2(c,B+' · 3','AI tạo sinh (Generative AI)',card('Tạo nội dung mới',P('Mô hình <b>tự tạo nội dung mới</b>: văn bản, ảnh, âm thanh, mã.','Ví dụ: <b>ChatGPT</b> (OpenAI) — đột phá 2022.','Chatbot chỉ trả lời theo <b>menu cố định</b> thì <b>không</b> phải tạo sinh.')),T(tr('','Ưu điểm','Rủi ro',h=True)+tr('AI tạo sinh','nhanh, linh hoạt','<b>ảo giác</b>, sai, vi phạm bản quyền, lộ dữ liệu'))+KEY('<b>Ảo giác (hallucination)</b>: trả lời thuyết phục nhưng <b>không có thật</b>.')))
S.append(S2(c,B+' · 4','Ứng dụng theo lĩnh vực',card('Bảng tóm tắt',T(tr('Lĩnh vực','Ứng dụng AI',h=True)+tr('Y tế','chẩn đoán từ ảnh, hệ chuyên gia')+tr('Giáo dục','học thông minh, <b>cá nhân hoá</b> nội dung, đánh giá')+tr('Tài chính','phân tích giao dịch, <b>phát hiện gian lận</b>')+tr('Giao thông','xe tự lái')+tr('Môi trường','<b>AIoT</b>: giám sát môi trường, biến đổi khí hậu'))),KEY('<b>AIoT</b> = AI + IoT (Internet vạn vật).')))
S.append(S2(c,B+' · 4','Hệ chuyên gia và học máy',card('Thay đổi theo thời gian',P('<b>Hệ chuyên gia</b> ban đầu: dựa trên <b>luật suy diễn và tri thức</b> do chuyên gia nhập.','Nhờ <b>học máy</b>, nhiều hệ chuyên gia <b>tự học luật từ dữ liệu</b>.','Không phải bị thay bằng bảng tính, và vẫn cần dữ liệu.')),KEY('Học máy làm hệ chuyên gia <b>tự rút luật từ dữ liệu</b>.')))
S.append(S2(c,B+' · 5','Thiên lệch dữ liệu',card('Dữ liệu quyết định công bằng',P('Mô hình nhận mặt kém với nhóm người ít xuất hiện trong dữ liệu huấn luyện: <b>thiên lệch dữ liệu</b>.','Dữ liệu thiếu học sinh khá giỏi → dự đoán điểm lệch cho nhóm đó.','Cách giảm: <b>dữ liệu đa dạng, đại diện</b>; kiểm tra theo nhóm.')),T(tr('Không phải nguyên nhân','Lí do',h=True)+tr('Đường truyền chậm','không liên quan độ công bằng')+tr('Lỗi cú pháp','lỗi chương trình, không phải thiên lệch')+tr('Xung đột tín hiệu mạng','chuyện của tầng mạng'))))
S.append(S2(c,B+' · 5','Quyền riêng tư, trách nhiệm, việc làm',card('Khi dùng AI cần',P('<b>Kiểm chứng</b> kết quả, không tin tuyệt đối; <b>ghi nguồn</b>.','<b>Bảo vệ dữ liệu cá nhân</b>: thu thập có mục đích, được đồng ý, bảo mật. Chatbot lưu tin nhắn phụ huynh → vấn đề dữ liệu cá nhân.','Xác định <b>ai chịu trách nhiệm</b>; AI <b>có thể ảnh hưởng việc làm</b>.')),T(tr('Phát biểu','Đúng?',h=True)+tr('Dữ liệu em nhập chắc chắn không ai xem','<b>Sai</b>')+tr('AI tạo sinh không sao chép bản quyền','<b>Sai</b>')+tr('Chỉ cần tốc độ, bỏ qua đạo đức','<b>Sai</b>'))))
S.append(SELF(c,B+' · 6','Tự kiểm tra 1: có phải AI?','Dây chuyền lắp ráp lặp lại cố định có phải AI không? Hệ thống gợi ý video học từ lịch sử xem thì sao?','',P('Dây chuyền: <b>tự động hoá</b>, không phải AI.','Gợi ý video: <b>AI</b>, thể hiện khả năng <b>học</b>.'),22))
S.append(SELF(c,B+' · 6','Tự kiểm tra 2: xe tự lái','Xe dùng radar và camera phát hiện xe, biển báo, người đi bộ. Khả năng nào?','',P('<b>Nhận thức</b> (cảm nhận môi trường qua cảm biến).'),22))
S.append(SELF(c,B+' · 6','Tự kiểm tra (HSG): đúng hay sai?','(a) Chương trình chỉ chơi cờ vua là AI tổng quát. (b) Chatbot menu “gõ 1…” là AI tạo sinh. (c) AI tạo sinh luôn đúng. (d) Nhận mặt sai ở một nhóm có thể do dữ liệu thiếu đại diện. (e) AI tổng quát đã triển khai rộng rãi.','',P('(a) <b>Sai</b>: AI hẹp.','(b) <b>Sai</b>: kịch bản cố định.','(c) <b>Sai</b>: có ảo giác.','(d) <b>Đúng</b>.','(e) <b>Sai</b>: vẫn là mục tiêu.'),20))
